Lprecipitation = zeros(numel(target.ranges),1);
end

%%
% Predict SNR available at the receiving antenna and system processing gain
function [availableSNR,processingGain,refRCS,refRange,constraint,detThreshold] = predictSNR(radar,target, refPd)
% Calculate propagation factor
Fprop = propagationFactor(radar,target);

% Calculate environmental losses
[Lgas,Llens,Lprecipitation] = atmosphericLosses(target);
Latmos = sum([Lgas Llens Lprecipitation], 2);

% Calculate range-dependent factors
Fcustom = rangeDependentLosses();


% Calculate signal-to-noise ratio (SNR)
availableSNR = radareqsnr(radar.Wavelength,target.ranges,radar.PeakPower, ...
    radar.Pulsewidth,'Gain',radar.Gain,'RCS',target.RCS,'Ts',radar.SystemTemperature, ...
    'PropagationFactor',Fprop,'AtmosphericLoss',Latmos,'CustomFactor',Fcustom); % dB

% Set design requirements
% Just used for plotting purposes
% constraint.Pd = 7.5000e-01; % Decimal, Threshold
constraint.Pd = 9.0000e-01; % Decimal, Objective
constraint.Range = 3.5000e+04; % m

% Calculate detectability
[detThreshold,DetComponents,componentNames,processingGain] = effectiveDetectability(refPd,radar);
fluctuationLossIdx = contains(componentNames,'Fluctuation loss','IgnoreCase',true);
if any(fluctuationLossIdx)
    fluctuationLoss = DetComponents(fluctuationLossIdx);
else
    fluctuationLoss = 0;
end

% Reference target and range
% Choose RCS to prevent extrapolation in interp1()
refTargetRCS = 10; % (m^2)
refAvailableSNR = radareqsnr(radar.Wavelength,target.ranges,radar.PeakPower, ...
    radar.Pulsewidth,'Gain',radar.Gain,'RCS',refTargetRCS,'Ts',radar.SystemTemperature, ...
    'PropagationFactor',0,'AtmosphericLoss',0,'CustomFactor',0); % dB

% The radarDataGenerator accounts for target fluctuation (if any) during detection and not during its setup
refRange = interp1(refAvailableSNR,target.ranges,detThreshold-fluctuationLoss,'spline','extrap');
refRCS = pow2db(refTargetRCS); % (dBsm)
end

