function [radarPlotter,FOVPlotter,targetPlotter,targetDetPlotter,falseAlarmDetPlotter] = createTP(waypoints, trajectory, radarPlat, targetPlat)
radarSensorModel = radarPlat.Sensors{1};
figure('Name','Animated Plot');
ax = gca;
tp = theaterPlot('XLimits',[min(waypoints(:,1))*.1 max(waypoints(:,1))],...
    'ZLimits',max(waypoints(:,1))*[-1 1],'YLimits',max(waypoints(:,1))*[-1 1],...
    'AxesUnits',["km","km","km"],'Parent',ax);
view(40,15);grid on;
legend('Location','northwest','BackgroundAlpha',.6)
title('Live Radar Simulation')

trajPlotter = trajectoryPlotter(tp,'DisplayName','Trajectory','LineWidth',2);
plotTrajectory(trajPlotter,{trajectory.Waypoints})

targetPlotter = platformPlotter(tp,'DisplayName','Target', ...
    'Marker','s','MarkerSize',10);
plotPlatform(targetPlotter,targetPlat.Position, ...
    targetPlat.Dimensions,quaternion(targetPlat.Orientation,'rotvecd'))

radarPlotter = platformPlotter(tp,'DisplayName','Radar','Marker','^','MarkerSize',10);
plotPlatform(radarPlotter,radarPlat.Position)
targetDetPlotter = detectionPlotter(tp,'DisplayName','Target Detection','Marker','x','MarkerSize',15);
falseAlarmDetPlotter = detectionPlotter(tp,'DisplayName','False Alarms','MarkerSize',5);

FOVPlotter = coveragePlotter(tp,'DisplayName','Sensor Coverage');
config = coverageConfig(radarSensorModel);
config.Position = radarPlat.Position + radarSensorModel.MountingLocation;
plotCoverage(FOVPlotter,config)
end

