% Static Plot
function staticPlot(simSNR,simRanges,target,radar,availableSNR,processingGain,...
    targetDetectionCoords,allFalseAlarmDetectionCoords,targetGTPoses,radarGTPoses,...
    detThreshold,constraint)
plotSNRError(simSNR,simRanges,target,radar,availableSNR,processingGain,detThreshold,constraint);
