% Compare Expected and Simulated SNR
function plotSNRError(simSNR,simRanges,target,radar,availableSNR,processingGain,detThreshold,constraint)
f = figure('Name', 'SNR vs Range');
f.Position(3:4) = [1000 500];
ax = subplot(2,2,[1,3]);
metricPlot = radarmetricplot(target.ranges*1.0000e-03,availableSNR,detThreshold, ...
    'RadarName',{'Available SNR (expected)'}, ...
    'MetricName','SNR', ...
    'MaxRangeRequirement',constraint.Range*1.0000e-03,...
    'RequirementName','Detectability (Available SNR)', ...
    'RangeUnit','km', ...
    'MetricUnit','dB', ...
    'ShowStoplight',true,...
    'Parent',ax);
hold on

plot(target.ranges/1e3,availableSNR+processingGain,'DisplayName','Radar SNR (expected)','LineWidth',1.5)
scatter(simRanges/1e3,simSNR,'filled','o','DisplayName','Radar SNR (simulated)','LineWidth',1,'MarkerFaceAlpha',.4)
if radar.UnambiguousRange < max(target.ranges)
    xline(radar.UnambiguousRange/1e3,'--','DisplayName','Max Unambiguous Range')
end

subplot(2,2,2)
predSNR = interp1(target.ranges,availableSNR+processingGain,simRanges);
SNRerror = abs(simSNR-predSNR);
SNRerror(1) = NaN; % Close ranges have numerical instability
plot(simRanges/1e3,SNRerror,'.','LineWidth',1)
title('SNR Error')
xlabel('Target Range (km)')
ylabel('SNR (dB)')
grid
if max(SNRerror) - min(SNRerror) < 2
    ylim([min(SNRerror)-1,max(SNRerror)+1])
else
    axis padded
end
xlim(metricPlot.XLim)
end

% Scenario Geometry
function plotScenario(simSNR,targetDetectionCoords,falseAlarmDetectionCoords,targetGTPoses,radarGTPoses)
subplot(2,2,4)
hold on
grid on
colormap parula
c = colorbar;
c.Label.String = 'SNR (dB)';
title('Scenario Geometry')
xlabel('X (km)')
ylabel('Z (km)')
legend('BackgroundAlpha',.6)

if ~isempty(falseAlarmDetectionCoords)
    scatter(falseAlarmDetectionCoords(:,1)/1e3,falseAlarmDetectionCoords(:,3)/1e3,50,'o','DisplayName','False Alarms');
end
scatter(targetDetectionCoords(:,1)/1e3,targetDetectionCoords(:,3)/1e3,50,simSNR,'o','filled','DisplayName','Target Detections');
plot(targetGTPoses(:,1)/1e3,targetGTPoses(:,3)/1e3,'.','DisplayName','Target Platform Truth');
plot(radarGTPoses(:,1)/1e3,radarGTPoses(:,3)/1e3,'^','DisplayName','Radar Platform Truth','LineWidth',2);
axis padded
end

% Find the detection indices for the target and the false alarms
function [targetDetIdx, falseAlarmDetIdx] = findDetIdx(dets)
% The TargetIdx property is nonnegative for detections from true targets
targetDetIdx = cellfun(@(x) x.ObjectAttributes{1,1}.TargetIndex >=0, dets, 'UniformOutput', 1);
targetDetIdx = find(targetDetIdx, 1); % Assumes only one target detection
falseAlarmDetIdx = 1:numel(dets);
falseAlarmDetIdx(targetDetIdx) = [];
end

%%
% Get indices of geometrically valid ranges
function idxs = getValidRangeIdxs(radar,target,env)
anht = radar.Height + 2*env.SurfaceHeightStandardDeviation;
tgtht = inf;
minRng = 0;
maxRng = 2*env.EffectiveEarthRadius + tgtht + anht;
idxs = (target.ranges >= minRng & target.ranges <= maxRng);
end

%%
% Effective detectability factor for the selected radar
function [Dx,Dc,componentNames,processingGain] = effectiveDetectability(Pd,radar)
Pfa = radar.Pfa;
[Dc,componentNames] = detectabilityComponents(Pd,Pfa,radar.NumNonCoherentPulses);
Dx = sum(Dc,2);
processingGain = -sum(Dc(:,2:end),2);
end

%%
% Losses and gains included in the detectability factor
function [Dc,names] = detectabilityComponents(Pd,Pfa,N)
% Single-pulse steady target
D01 = detectability(Pd,Pfa,1,'Swerling0');
% Noncoherent integration gain
D0N = detectability(Pd,Pfa,N);
Gni = D0N - D01;

Dc = [D01 Gni];
names = {'Single-pulse steady target' 'Noncoherent integration gain'};
end
